    .attr("width", width)
    .attr("height", height);

const tooltip = d3.select("#tooltip");

d3.csv("data/stock-descriptions.csv").then(data => {
    // Process data
    data.forEach(d => {
        d.marketCapVal = parseFloat(d.marketCap);
        d.isETF = isNaN(d.marketCapVal) || d.marketCap === "";
    });

    const sectors = Array.from(new Set(data.map(d => d.sector))).sort();

    // Scales
    const colorScale = d3.scaleOrdinal()
        .domain(sectors)
        .range(d3.schemeCategory10);

    // Filter valid caps for scale domain
    const validCaps = data.filter(d => !d.isETF).map(d => d.marketCapVal);
    const minCap = d3.min(validCaps);
    const maxCap = d3.max(validCaps);

    const sizeScale = d3.scaleSqrt()
        .domain([minCap, maxCap])
        .range([15, 60]); 

    const getRadius = (d) => {
        if (d.isETF) return 20; 
        return sizeScale(d.marketCapVal);
    };

    // Force Simulation Centers
    const xCenter = d3.scalePoint()
        .domain(sectors)
        .range([100, width - 100])
        .padding(0.5);

    const simulation = d3.forceSimulation(data)
        .force("charge", d3.forceManyBody().strength(5))
        .force("collide", d3.forceCollide().radius(d => getRadius(d) + 2).strength(0.7))
        .force("x", d3.forceX(d => xCenter(d.sector)).strength(0.4))
        .force("y", d3.forceY(height / 2).strength(0.15))
        .on("tick", ticked);

    // Draw Bubbles
    const node = svg.selectAll(".node")
        .data(data)
        .enter().append("g")
        .attr("class", "node")
        .call(drag(simulation));

    const circles = node.append("circle")
        .attr("r", d => getRadius(d))
        .attr("fill", d => colorScale(d.sector))
        .attr("stroke", "#fff")
        .attr("stroke-width", 1.5)
        .on("mouseover", (event, d) => {
            if (d.isETF) return;
            tooltip.transition().duration(200).style("opacity", .9);
            tooltip.html(`<strong>${d.ticker}</strong><br>${d["full name"]}<br>${d.sector}`)
                .style("left", (event.pageX + 10) + "px")
                .style("top", (event.pageY - 28) + "px");
        })
        .on("mouseout", (event, d) => {
            tooltip.transition().duration(500).style("opacity", 0);
        })
        .on("click", (event, d) => highlight(d));

    const labels = node.append("text")
        .text(d => d.ticker)
        .attr("text-anchor", "middle")
        .attr("dy", ".35em")
        .style("font-size", "10px")
        .style("pointer-events", "none");

    function ticked() {
        node.attr("transform", d => {
            // Keep within bounds
            const r = getRadius(d);
            d.x = Math.max(r, Math.min(width - r, d.x));
            d.y = Math.max(r, Math.min(height - r, d.y));
            return `translate(${d.x},${d.y})`;
        });
    }

    // Legend
    const legend = svg.selectAll(".legend")
        .data(sectors)
        .enter().append("g")
        .attr("class", "legend")
        .attr("transform", (d, i) => `translate(20, ${20 + i * 20})`);

    legend.append("rect")
        .attr("x", 0)
        .attr("width", 12)
        .attr("height", 12)
        .style("fill", colorScale);

    legend.append("text")
        .attr("x", 18)
        .attr("y", 6)
        .attr("dy", ".35em")
        .text(d => d)
        .style("font-size", "12px");

    // Table
    const tableArea = d3.select("#table-area");
    const table = tableArea.append("table");
    const thead = table.append("thead");
    const tbody = table.append("tbody");

    const columns = ["Ticker symbol", "Full company name", "Sector", "Market cap"];

    thead.append("tr")
        .selectAll("th")
        .data(columns)
        .enter()
        .append("th")
        .text(d => d);

    const rows = tbody.selectAll("tr")
        .data(data)
        .enter()
        .append("tr")
        .attr("id", d => "row-" + d.ticker)
        .on("click", (event, d) => highlight(d));

    rows.selectAll("td")
        .data(d => {
            return [
                d.ticker,
                d["full name"],
                d.sector,
                formatMarketCap(d.marketCapVal)
            ];
        })
        .enter()
        .append("td")
        .text(d => d);

    function formatMarketCap(val) {
        if (!val || isNaN(val)) return "N/A";
        if (val >= 1e12) return (val / 1e12).toFixed(2) + "T";
        if (val >= 1e9) return (val / 1e9).toFixed(2) + "B";
        if (val >= 1e6) return (val / 1e6).toFixed(2) + "M";
        return val;
    }

    function highlight(d) {
        circles.attr("stroke", "#fff").attr("stroke-width", 1.5);
        rows.classed("selected", false);

        circles.filter(data => data.ticker === d.ticker)
            .attr("stroke", "#000")
            .attr("stroke-width", 3)
            .raise(); // Bring to front

        const selectedRow = rows.filter(data => data.ticker === d.ticker);
        selectedRow.classed("selected", true);

        const rowNode = selectedRow.node();
        if (rowNode) {
            rowNode.scrollIntoView({ behavior: "smooth", block: "center" });
        }
    }

    function drag(simulation) {
        function dragstarted(event, d) {
            if (!event.active) simulation.alphaTarget(0.3).restart();
            d.fx = d.x;
            d.fy = d.y;
        }

        function dragged(event, d) {
            d.fx = event.x;
            d.fy = event.y;
        }

        function dragended(event, d) {
            if (!event.active) simulation.alphaTarget(0);
            d.fx = null;
            d.fy = null;
        }

        return d3.drag()
            .on("start", dragstarted)
            .on("drag", dragged)
            .on("end", dragended);
    }
});
EOF
